  case m matches /\d{2}\/\d{2}\/\d{4}/ -> d as Date {format: "MM/dd/yyyy"} as String {format: "yyyy-MM-dd"}
  else -> d as Date {format: "yyyyMMdd"} as String {format: "yyyy-MM-dd"}
}

